from common import ROOT,read
from paper_utils import Paper,fmt,label,interval

def main():
    r=read(ROOT/'artifacts/results.json');m=r['metrics'];choice=read(ROOT/'artifacts/selection.json');audit=read(ROOT/'artifacts/audit.json');config=read(ROOT/'project.json');selected=m['selected'];boot=r['bootstrap']['comparisons'];cases=read(ROOT/'artifacts/error_analysis.json')['cases'];runtime=read(ROOT/'artifacts/neural_runtime.json');cfg=choice['selected']
    p=Paper('Поиск русскоязычных биомедицинских текстов: опубликованные RusBEIR baselines, гибридный поиск и согласование rerankers')
    p.h('Abstract')
    p.p(f'Оценивается ранжирование русскоязычных биомедицинских документов по короткому текстовому запросу. Используется полный официальный rus-NFCorpus из RusBEIR: 3633 документа и 323 test query с градуированными qrels. Сравниваются BM25, multilingual E5-small/E5-large, Qwen3 embeddings и BGE reranking. Собственный вариант объединяет лексический и семантический поиск через RRF, затем согласует BGE и Qwen3 rerankers; веса выбираются только по официальному dev. Основной показатель - точный TREC nDCG@10 с линейным gain. Выбранный метод получает {fmt(selected["ndcg_cut_10"])} против {fmt(m["bm25_bge_reranker512"]["ndcg_cut_10"])} у воспроизведённого BM25+BGE; парный 95% интервал разности составляет {interval(boot["bm25_bge_reranker512"]["ci95"])}. Описаны отклонения CPU BM25 от Elasticsearch статьи, влияние длины контекста, частичная разметка и регрессии отдельных запросов. Глобальное SotA не заявляется.')
    p.p('Репозиторий: '+config['repository_url'])
    p.h('1. Introduction')
    p.p('Лексический поиск требует совпадения слов, тогда как пользователь может сформулировать запрос иным выражением или синонимом. В научных документах важны редкие термины, но релевантность часто определяется отношением между понятиями и контекстом. Это естественная задача NLP: модель читает текст запроса и документа; идентификаторы, qrels и служебные поля не служат признаками.')
    p.p('RQ1: насколько готовые семантические модели выигрывают или проигрывают сильному лексическому baseline в выбранном русском домене; RQ2: даёт ли объединение кандидатов дополнительную релевантность; RQ3: оправдано ли согласование двух rerankers и увеличение token budget. Собственный вклад - проверяемая композиция опубликованных компонентов с dev-адаптацией, а не новая foundation model или генератор научных ответов.')
    p.h('2. Related Work')
    p.p('BEIR [1] предложил разнородную оценку zero-shot информационного поиска. RusBEIR [2] переносит эту идею на русский язык и публикует сравнения на rus-NFCorpus. В его таблице nDCG@10 для этого корпуса BM25 равен .3233, multilingual E5-large .3096, BM25+BGE .3483. Эти значения относятся к исходной конфигурации авторов, а не к нашим измерениям.')
    p.p('Multilingual E5 [3] использует контрастивное обучение представлений. Для inference существенны query:/passage: prefixes, masked mean pooling и нормализация; замена этих деталей меняет метод. BGE [4] предлагает отдельный cross-encoder reranker, который совместно читает пару. Qwen3 Embedding [5] содержит как encoder представлений, так и yes/no reranker с явной инструкцией. Мы сохраняем официальные способы pooling и оформления запросов.')
    p.p('Reciprocal Rank Fusion [6] объединяет ранжирования, не требуя сопоставимой шкалы score. Это удобно для BM25 и dense cosine. В отличие от фиксированного zero-shot baseline, окончательные веса нашего метода подбираются на dev. Поэтому улучшение такой композиции не следует выдавать за строго zero-shot результат той же постановки. Статья о RusBEIR служит опубликованным previous art на конкретном dataset, а не только общей ссылкой на похожую задачу.')
    p.table(['Система','Сохранённая часть','Адаптация'],[
      ['BM25','Авторские processed_* поля, Lucene формула','Текущий CPU BM25s объединяет title/text; это отличается от Elasticsearch best_fields статьи'],
      ['E5-small / large','Официальные веса, prefixes, masked mean, L2, 512 tokens','Локальный Transformers inference, FP32'],
      ['BGE reranker','Top-20, pair classification','512-token cap следует pinned коду; статья упоминает 2048. BF16 вместо FP32'],
      ['Qwen embedding','Официальные веса, last-token pooling, L2','Доменная query-инструкция, 512 tokens'],
      ['Qwen reranker','Официальный system/user/assistant template, yes/no probability','512/2048 token budgets, protected prefix/suffix, BF16']],[1.4,2,2.5])
    p.h('3. Model Description')
    p.p('Sparse baseline индексирует title и text после поставляемой авторами нормализации: processed_title/processed_text уже содержат лемматизацию и удаление stopwords. Используется BM25s Lucene, k1=1.2, b=.75. Контроль raw-text убирает эту предобработку. Двухполевой математический контроль вычисляет max(field scores)+.5*min(field scores); он приближает best_fields tie breaker, но не объявляется битовым воспроизведением Elasticsearch.')
    p.p('Dense методы кодируют title + newline + text. E5 получает query: и passage: prefixes, среднее скрытых состояний по attention mask, затем L2 нормализацию. Для Qwen применяются last-token pooling при left padding, нормализация и английская инструкция поиска биомедицинских фрагментов. Максимальная длина - 512 tokens, счётчики усечений записаны. Косинус считается точным умножением матриц по всем 3633 документам; approximate nearest-neighbor index не используется.')
    p.p('Первый собственный этап объединяет top-100 BM25 и top-100 Qwen embedding. RRF score(d)=sum 1/(60+rank(d)); в отсутствие документа в одном списке его вклад равен нулю. После fusion сохраняется top-100. Reranking переставляет top-20 кандидатов, а хвост 21-100 сохраняет исходный порядок. Поэтому Recall@100 ограничивается retrieval stage и не улучшается от одной перестановки top-20.')
    p.p('BGE совместно читает пару query/document; вход каждого текста ограничен 8192 символами, пара - 512 tokens, как в зафиксированном авторском wrapper. Qwen reranker получает официальный шаблон с <Instruct>, <Query>, <Document> и фиксированным ответным suffix. Вероятность yes вычисляется относительно yes/no logits, только для последнего токена. Этот ограниченный score не интерпретируется как калиброванная вероятность релевантности.')
    p.p('Последний этап складывает reciprocal ranks BGE, Qwen и исходного retrieval. На dev перебираются Qwen weights 0/.25/.5/.75/1, complementary BGE weight, retrieval weights 0/.1/.25 и контексты 512/2048: всего 30 конфигураций. Все одиночные системы остаются в сравнении. Нулевой вес компонента означает, что dev не обнаружил пользы его добавления.')
    p.p(f'Зафиксированный выбор: Qwen context {cfg["length"]}, Qwen weight {cfg["qwen_weight"]}, BGE weight {cfg["bge_weight"]}, retrieval weight {cfg["retrieval_weight"]}. Настройки test после этого не изменяются. Обучение foundation weights на benchmark не проводится; это вариант dev-adapted fusion готовых языковых моделей.')
    p.h('4. Dataset')
    p.p('Используются официальные kaengreg/rus-nfcorpus и rus-nfcorpus-qrels с зафиксированными revision и SHA. Корпус включает 3633 документа; query ids и document ids проверяются на уникальность, пустых документов не обнаружено. Все официальные train/dev/test query ids сохраняются и не пересекаются. Размеры:')
    p.table(['Официальный split','Queries','Qrels','Число grade 2'],[[s,audit['splits'][s]['queries'],audit['splits'][s]['qrels'],audit['splits'][s]['grades'].get('2',0)] for s in ['train','dev','test']],[2,1,1.5,1.5])
    p.p('Train qrels доступны, но в этом исследовании не используются для градиентного обучения. Dev используется для выбора fusion. Несмотря на упрощённое описание в исходной таблице статьи, реальные dev/test qrels содержат grades 1 и 2; они сохраняются. Восьми dev и шести test query text соответствуют нормализованные тексты из train, что отмечено в аудите. Поскольку train labels не используются, это не является прямой утечкой supervised модели, но ограничивает разнообразие корпуса.')
    p.p('Qrels отражают доступную разметку, а не все возможные истинно релевантные документы. Непомеченный документ получает ноль по правилам benchmark; это не доказательство его смысловой нерелевантности. Перевод исходного NFCorpus и научная специфика также ограничивают перенос результата на произвольный русский поиск.')
    p.h('5. Experiments')
    p.p('Главная метрика - pytrec_eval nDCG@10, та же библиотека TREC, которую вызывает исходный evaluator RusBEIR. Gain линейный по grade; exponential DCG из других пакетов не подставляется. Дополнительно считаются MAP@10, Recall@10/100, P@10 и MRR@10. При равных score порядок фиксирован doc id; для экспорта сохраняются rank scores, чтобы библиотечный tie breaker его не менял.')
    p.p('Контрольный пример с grades 2/1/1 и исходная функция EvaluateRetrieval.evaluate дают тот же результат, что наш thin wrapper. Код upstream без явной top-level лицензии не перепубликуется: сохраняются source hashes, а проверка функции выполнена по локальному pinned source. Основной runtime использует свободный pytrec-eval-terrier 0.5.11 и собственную адаптацию API.')
    p.p('Генераторы embeddings и ранжирований не читают qrels. Dev evaluator читает только development_qrels.json. Выбор и SHA всех runs фиксируются в evaluation_lock, затем открывается отдельный test qrels файл. Парный bootstrap по queries использует 2000 повторов с seed 10. Формирование длинных logits оптимизировано до последнего токена без изменения yes/no формулы. Реальные версии и время сохранены; inference выполняется на RTX 3060 Laptop 6GB.')
    p.h('6. Results')
    p.table(['Метод','Dev nDCG10','Test nDCG10','MAP10','R@100'],[[label(n),fmt(choice['methods']['selected_fusion' if n=='selected' else n]['ndcg_cut_10']),fmt(v['ndcg_cut_10']),fmt(v['map_cut_10']),fmt(v['recall_100'])] for n,v in m.items()],[2.9,1.25,1.25,1,1])
    p.figure('main.png','Рисунок 1. Все измеренные системы на 323 официальных test queries; значения статьи приводятся отдельно от этой таблицы.')
    p.p(f'Выбранная по dev система получает test nDCG@10 {fmt(selected["ndcg_cut_10"])} с 95% CI {interval(r["selected_test_ndcg95"])}. Разность относительно нашего BM25+BGE равна {fmt(boot["bm25_bge_reranker512"]["delta"])}. '+('Интервал разности выше нуля.' if boot['bm25_bge_reranker512']['ci95'][0]>0 else 'Интервал не позволяет утверждать устойчивое положительное превосходство.'))
    p.table(['Selected минус','Разность nDCG10','Парный 95% CI'],[[label(n),fmt(v['delta']),interval(v['ci95'])] for n,v in boot.items()],[2.9,1.2,2])
    p.figure('uncertainty.png','Рисунок 2. Парные bootstrap интервалы; единица ресэмплинга - официальный query.')
    p.p('Сравнение raw/processed BM25 проверяет пользу языковой нормализации; single-field/two-field контроль - чувствительность движка к полям. E5 small/large проверяет размер encoder, RRF против отдельных retrievers - состав кандидатов, Qwen reranker 512/2048 - контекст. Это несколько заранее определённых сравнений; отсутствие улучшения не скрывается.')
    p.figure('robustness.png','Рисунок 3. Изменения по отдельным queries: даже положительное среднее может сопровождаться заметными регрессиями.')
    p.table(['Нейронный этап','Секунды текущего запуска'],[[n,fmt(v.get('seconds',v.get('corpus',{}).get('seconds',0)+v.get('queries',{}).get('seconds',0)),1)] for n,v in runtime.items()],[3,2])
    p.p('Runtime - измеренное wall-clock время с описанным кэшем. При возобновлении reranker manifest отдельно показывает число новых и уже кэшированных пар. Это не утверждение о latency сервиса и не сравнение с аппаратурой из статьи. Полные rankings, relevance grades и ideal gains позволяют пересчитать nDCG/MAP/recall из публичных файлов без весов.')
    p.h('6.1. Error analysis and limitations')
    p.p('Для качественного разбора автоматически берутся запросы с наибольшим выигрышем, наибольшей регрессией и медианной разностью nDCG относительно BM25+BGE. Такой выбор явно показывает крайние случаи, а не оценивает их долю. Ниже перечислены первые три результата и их исходные qrels grades.')
    for e in cases:
        p.p(f'{e["type"]}: {e["query"]} Разность nDCG={fmt(e["ndcg_delta"])}.')
        for name,items in e['rankings'].items():p.p(name+': '+'; '.join(f'{x["title"]} [grade={x["grade"]}]' for x in items))
    p.p('Ограничения: единственный домен, 323 query, неполные qrels, переводные тексты и возможная неизвестная экспозиция pretrained моделей. Dev grid сам по себе даёт преимущество перед строго zero-shot comparators. CPU BM25 отличается от исходного Elasticsearch, BGE token cap берётся из кода, а не из отличающегося описания статьи. Top-20 reranking не может вернуть документ, отсутствующий среди кандидатов. Поэтому превосходство в данной таблице не эквивалентно доказанному мировому SotA.')
    p.h('7. Conclusion')
    p.p(f'Создан воспроизводимый текстовый retrieval benchmark с реальными опубликованными конкурентами на том же официальном dataset. Итоговая dev-adapted композиция даёт nDCG@10 {fmt(selected["ndcg_cut_10"])}; её вклад оценивается по парным интервалам и всем абляциям. Главный результат - измеренное поведение lexical/dense/reranking компонентов при явных ограничениях, а не перенос чужой цифры из статьи в собственную таблицу.')
    p.references(['Thakur et al. 2021. BEIR: A Heterogeneous Benchmark for Zero-shot Evaluation of Information Retrieval Models. NeurIPS Datasets and Benchmarks. https://arxiv.org/abs/2104.08663','Kovalev et al. 2025. Building Russian Benchmark for Evaluation of Information Retrieval Models. https://arxiv.org/abs/2504.12879','Wang et al. 2024. Multilingual E5 Text Embeddings: A Technical Report. https://arxiv.org/abs/2402.05672','BAAI. bge-reranker-v2-m3 official checkpoint and usage. https://huggingface.co/BAAI/bge-reranker-v2-m3','Zhang et al. 2025. Qwen3 Embedding: Advancing Text Embedding and Reranking Through Foundation Models. https://arxiv.org/abs/2506.05176','Cormack, Clarke and Büttcher. 2009. Reciprocal rank fusion outperforms condorcet and individual rank learning methods. SIGIR. https://doi.org/10.1145/1571941.1572114','kaengreg. RusBEIR source and data release. https://github.com/kaengreg/rusBEIR'])
    p.finish()
if __name__=='__main__':
    if (ROOT/'experiments/phase2/artifacts/final_results.json').exists():
        from make_paper_phase2 import main as phase2_main
        phase2_main()
    else:main()
